const INSPECT_SYMBOL = Symbol.for('nodejs.util.inspect.custom');

export class TextField {
  constructor(options = {}) {
    this.analyzer = options.analyzer ?? null;
  }
}

export function TEXT(options = {}) {
  return new TextField(options);
}

export class Schema {
  constructor(fields = {}) {
    this.fields = { ...fields };
  }

  toString() {
    const names = Object.keys(this.fields).map((name) => `'${name}'`).join(', ');
    return `<Schema: [${names}]>`;
  }

  [INSPECT_SYMBOL]() {
    return this.toString();
  }
}

