import { formatError, formatHelp } from './formatter.mjs';
import { basename } from './path.mjs';

const NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;

function buildFailure(programName, message) {
  return {
    ok: false,
    exitCode: 2,
    output: formatError(programName, message),
    programName,
    stream: 'stderr',
  };
}

function classifyHelpToken(token) {
  if (token === '-h') {
    return { type: 'help' };
  }

  if (token.startsWith('-h') && !token.startsWith('--')) {
    if (token.startsWith('-h=')) {
      return { explicitArg: token.slice(3), type: 'help_error' };
    }

    if (token.length > 2) {
      return { type: 'help' };
    }
  }

  if (!token.startsWith('--')) {
    return null;
  }

  const equalsIndex = token.indexOf('=');
  const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);

  if (optionName.length <= 2 || !'--help'.startsWith(optionName)) {
    return null;
  }

  if (equalsIndex !== -1) {
    return {
      explicitArg: token.slice(equalsIndex + 1),
      type: 'help_error',
    };
  }

  return { type: 'help' };
}

function isValueToken(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '-') {
    return true;
  }

  if (!token.startsWith('-')) {
    return true;
  }

  return NEGATIVE_NUMBER_PATTERN.test(token);
}

export function parseTest3Args(argv, scriptPath) {
  const programName = basename(scriptPath) || 'test3.mjs';
  const extras = [];
  let aValue = '';
  let hasA = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];
    const help = classifyHelpToken(token);

    if (help !== null) {
      if (help.type === 'help_error') {
        return buildFailure(
          programName,
          `argument -h/--help: ignored explicit argument '${help.explicitArg}'`,
        );
      }

      return {
        ok: false,
        exitCode: 0,
        output: formatHelp(programName),
        programName,
        stream: 'stdout',
      };
    }

    if (token === '--a') {
      const nextToken = argv[index + 1];

      if (!isValueToken(nextToken)) {
        return buildFailure(programName, 'argument --a: expected one argument');
      }

      hasA = true;
      aValue = nextToken;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      hasA = true;
      aValue = token.slice(4);
      continue;
    }

    if (token === '--') {
      extras.push(...argv.slice(index));
      break;
    }

    extras.push(token);
  }

  if (!hasA) {
    return buildFailure(programName, 'the following arguments are required: --a');
  }

  if (extras.length > 0) {
    return buildFailure(programName, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return {
    ok: true,
    programName,
    values: { a: aValue },
  };
}

